  'Please enter a 6-digit verification code.' => 'ཨང་གྲངས་༦ འབད་མི་ བདེན་དཔྱད་ཨང་རྟགས་ཅིག་བཙུགས་གནང་།',
  'Two-factor authentication enabled.' => 'ཆ་རྐྱེན་གཉིས་ཀྱི་བདེན་བཤད་ལྕོགས་ཅན་བཟོ་ཡོདཔ།',
  'Unable to enable two-factor authentication.' => 'ཆ་རྐྱེན་གཉིས་ལྡན་གྱི་བདེན་བཤད་ལྕོགས་ཅན་བཟོ་མི་ཚུགས།',
  'Two-factor authentication disabled.' => 'ཆ་རྐྱེན་གཉིས་ཀྱི་བདེན་བཤད་ལྕོགས་མིན་བཟོ་ཡོདཔ།',
  'Unable to disable two-factor authentication.' => 'ཆ་རྐྱེན་གཉིས་ལྡན་གྱི་བདེན་བཤད་ལྕོགས་མིན་བཟོ་མི་ཚུགས།',
  'Changes discarded.' => 'བསྒྱུར་བཅོས་ཚུ་བཏོན་བཀོག་ཡོདཔ།',
  'Channel URL copied to clipboard.' => 'འཛིན་པང་ལུ་འདྲ་བཤུས་རྐྱབ་ཡོད་པའི་རྒྱུ་ལམ་ཡུ་ཨར་ཨེལ།',
  'Unable to copy the URL in this browser.' => 'བརྡ་འཚོལ་འདི་ནང་ ཡུ་ཨར་ཨེལ་འདྲ་བཤུས་རྐྱབ་མ་ཚུགས།',
  'Unable to copy text to clipboard.' => 'འཛིན་པང་ལུ་ཚིག་ཡིག་འདྲ་བཤུས་རྐྱབ་མ་ཚུགས།',
  'Settings saved successfully.' => 'སྒྲིག་སྟངས་ཚུ་མཐར་འཁྱོལ་ཅན་སྦེ་སྲུང་བཞག་འབད་ཡོདཔ།',
  'Unable to save settings.' => 'སྒྲིག་སྟངས་ཚུ་སྲུང་བཞག་འབད་མ་ཚུགས།',
