  'Use playlists and series to keep your content easy to find and watch.' => 'ཁྱོད་རའི་ནང་དོན་ཚུ་འཚོལ་ནི་དང་བལྟ་ནི་ལུ་འཇམ་ཏོང་ཏོ་སྦེ་བཞག་ནིའི་དོན་ལུ་ གླུ་གཞས་ཐོ་ཡིག་དང་རིམ་འབྱུང་ཚུ་ལག་ལེན་འཐབ།',
  'Copy profile link' => 'གསལ་སྡུད་འབྲེལ་ལམ་འདྲ་བཤུས།',
