  'Unable to copy profile link.' => 'གསལ་སྡུད་འབྲེལ་ལམ་འདྲ་བཤུས་རྐྱབ་མ་ཚུགས།',
  'Profile shared.' => 'གསལ་སྡུད་བརྗེ་སོར་འབད་ཡོདཔ།',
  'Share cancelled.' => 'བགོ་བཤའ་ཆ་མེད་བཏང་ཡོདཔ།',
  'Notifications muted for this profile.' => 'གསལ་སྡུད་འདི་གི་དོན་ལུ་ བརྡ་བསྐུལ་ཚུ་ སྒྲ་མེདཔ་བཟོ་ཡོདཔ།',
  'Notifications enabled for this profile.' => 'གསལ་སྡུད་འདི་གི་དོན་ལུ་ བརྡ་བསྐུལ་ཚུ་ལྕོགས་ཅན་བཟོ་ཡོདཔ།',
  'Profile added to favorites.' => 'གསལ་སྡུད་དགའ་གདམ་ཚུ་ལུ་ཁ་སྐོང་འབད་ཡོདཔ།',
  'Profile removed from favorites.' => 'དགའ་གདམ་ཚུ་ལས་གསལ་སྡུད་རྩ་བསྐྲད་གཏང་ཡོདཔ།',
  'Profile reported for review.' => 'བསྐྱར་ཞིབ་ཀྱི་དོན་ལུ་ གསལ་སྡུད་སྙན་ཞུ་འབད་ཡོདཔ།',
  'User blocked. Their content and notifications are hidden.' => 'ལག་ལེན་པ་བཀག་ཡོདཔ། ཁོང་གི་ནང་དོན་དང་བརྡ་བསྐུལ་ཚུ་སྦ་བཞག་ཡོདཔ་ཨིན།',
  'User unblocked.' => 'ལག་ལེན་པ་གིས་ བཀག་ཆ་མེདཔ་བཟོ་ཡོདཔ།',
  'Unblock this user before sending a message.' => 'འཕྲིན་དོན་མ་གཏང་པའི་ཧེ་མ་ ལག་ལེན་པ་འདི་བཀག་ཆ་བཤོལ།',
  'Message composer opened.' => 'འཕྲིན་དོན་རྩོམ་སྒྲིག་པ་ཁ་ཕྱེ་ཡོད།',
  'About' => 'སྐོར་ལས',
  'Channel details' => 'རྒྱུ་ལམ་ཁ་གསལ།',
  'Stats' => 'གནས་སྡུད།',
  'Totals' => 'དངོས་བསྡོམས་བསྡོམས།',
  'Tell viewers about your channel...' => 'ཁྱོད་རའི་བརྡ་འཕྲིན་གྱི་སྐོར་ལས་ ལྟདམོ་ལྟ་མི་ཚུ་ལུ་སླབ།',
  'Add an about section so viewers know what your channel is about.' => 'ཁྱོད་ཀྱི་རྒྱུན་ལམ་ག་ཅི་གི་སྐོར་ལས་ཨིན་ན་ ལྟདམོ་ལྟ་མི་ཚུ་གིས་ཤེས་ཚུགས་ནིའི་དོན་ལུ་ སྐོར་ལས་ དབྱེ་ཚན་ཁ་སྐོང་རྐྱབས།',
  'This channel has not added an about section yet.' => 'རྒྱུན་ལམ་འདི་གིས་ ད་ལྟོ་ཚུན་ཚོད་ སྐོར་ལས་ དབྱེ་ཚན་ཁ་སྐོང་མ་འབད་བས།',
  'Admin' => 'བདག་སྐྱོང་པ།',
  'Dashboard' => 'ཌེཤ་བོརཌི།',
  'Users' => 'ལག་ལེན་པ་ཚུ།',
  'Reports' => 'སྙན་ཞུ།',
  'Support' => 'རྒྱབ༌སྐྱོར',
  'Roles & Permissions' => 'འགན་ཁུར་དང་གནང་བ་ཚུ།',
  'System Settings' => 'རིམ་ལུགས་སྒྲིག་སྟངས་ཚུ།',
  'Monitor platform activity, moderation, revenue, and system health.' => 'སྡིངས་ཆ་གི་ལས་སྣ་དང་ བར་མཚམས་ འོང་འབབ་ དེ་ལས་ ལམ་ལུགས་གསོ་བའི་གནས་སྟངས་ཚུ་ ལྟ་རྟོག་འབད།',
  'Manage and monitor platform users, permissions, and activity.' => 'སྡིངས་ཆ་ལག་ལེན་པ་དང་ གནང་བ་ དེ་ལས་ ལས་སྣ་ཚུ་ འཛིན་སྐྱོང་དང་ ལྟ་རྟོག་འབད།',
  'Manage creators, channel performance, verification, and creator growth.' => 'གསར་བསྐྲུན་པ་དང་ རྒྱུན་ལམ་གྱི་ལཱ་འགན་ བདེན་དཔྱད་ དེ་ལས་ གསར་བསྐྲུན་པ་གི་ཡར་འཕར་ཚུ་ འཛིན་སྐྱོང་འཐབ།',
  'Manage videos, shorts, posts, and content moderation across the platform.' => 'བརྡ་འཕྲིན་དང་ ཐུང་ཐུང་ བརྡ་འཕྲིན་ དེ་ལས་ ནང་དོན་ཚུ་ སྟེགས་བུ་ནང་ འཛིན་སྐྱོང་འཐབ།',
  'Monitor live sessions, scheduling, stream health, and live moderation.' => 'ཐད་འཕྲོད་ཀྱི་ལཱ་ཡུན་དང་ དུས་ཚོད་བཀོད་ནི་ གསོ་བའི་རྒྱུན་ལམ་ དེ་ལས་ ཐད་འཕྲོད་ཀྱི་ བར་འཛུལ་ཚུ་ ལྟ་རྟོག་འབད།',
  'Review flagged content, user complaints, and platform safety incidents.' => 'བསྐྱར་ཞིབ་འབད་ཡོད་པའི་ནང་དོན་དང་ ལག་ལེན་པའི་ཉོགས་བཤད་ དེ་ལས་ སྟེགས་བུ་ཉེན་སྲུང་གི་བྱུང་རྐྱེན་ཚུ་ བསྐྱར་ཞིབ་འབད།',
  'Track revenue, payouts, subscriptions, ads, tips, and creator earnings.' => 'འོང་འབབ་དང་ དངུལ་ཕོགས་ མཐུན་རྐྱེན་ ཁྱབ་བསྒྲགས་ བསླབ་བྱ་ དེ་ལས་ གསར་བསྐྲུན་འབད་མི་གི་འོང་འབབ་ཚུ་ བརྟག་ཞིབ་འབད།',
  'Analyze platform growth, viewer behavior, engagement, and content performance.' => 'སྡིངས་ཆ་ཡར་འཕར་དང་ ལྟདམོ་ལྟ་མིའི་སྤྱོད་ལམ་ འབྲེལ་གཏོགས་དང་ ནང་དོན་གྱི་ལཱ་འགན་ཚུ་ དབྱེ་དཔྱད་འབད།',
  'Manage support tickets, help requests, escalations, and response quality.' => 'རྒྱབ་སྐྱོར་གྱི་ཤོག་བྱང་དང་ གྲོགས་རམ་གྱི་ཞུ་བ་ ཡར་སེང་ དེ་ལས་ ལན་འདེབས་སྤུས་ཚད་ཚུ་ འཛིན་སྐྱོང་འཐབ།',
  'Manage admin roles, access levels, team members, and security permissions.' => 'བདག་སྐྱོང་འགན་ཁུར་དང་ འཛུལ་སྤྱོད་གནས་རིམ་ སྡེ་ཚན་གྱི་འཐུས་མི་ དེ་ལས་ ཉེན་སྲུང་གི་གནང་བ་ཚུ་ འཛིན་སྐྱོང་འཐབ།',
  'Configure platform preferences, integrations, security, storage, and system behavior.' => 'སྟེགས་རིས་དགའ་གདམ་དང་མཉམ་བསྡོམས་ ཉེན་སྲུང་ གསོག་འཇོག་ དེ་ལས་ རིམ་ལུགས་སྤྱོད་ལམ་ཚུ་རིམ་སྒྲིག་འབད།',
  'Loading admin data...' => 'བདག་སྐྱོང་གནས་སྡུད་ངོ་མ་མངོན་གསལ་འབད་དོ།',
  'Sign in with an admin account to view this page.' => 'ཤོག་ལེབ་འདི་བལྟ་ནིའི་དོན་ལུ་ བདག་སྐྱོང་རྩིས་ཐོ་ཅིག་དང་གཅིག་ཁར་ནང་བསྐྱོད་འབད།',
