  'Mark generated users as verified' => 'བཟོ་བཏོན་འབད་ཡོད་པའི་ལག་ལེན་པ་ཚུ་ བདེན་བཤད་འབད་ཡོདཔ་སྦེ་རྟགས་བཀལ།',
  'Create channel profiles for generated users' => 'བཟོ་བཏོན་འབད་ཡོད་པའི་ལག་ལེན་པ་ཚུ་གི་དོན་ལུ་ རྒྱུ་ལམ་གསལ་སྡུད་ཚུ་གསར་བསྐྲུན་འབད།',
  'Generate random avatars' => 'གང་བྱུང་ཨ་ཝ་ཊར་ཚུ་བཟོ་བཏོན་འབད།',
  'Invite user' => 'ལག་ལེན་པ་མགྲོན་བརྡ་འབད།',
  'Create an account invite with a role assignment.' => 'ལས་འགན་ལས་འགན་དང་གཅིག་ཁར་ རྩིས་ཐོའི་མགྲོན་བརྡ་ཅིག་གསར་བསྐྲུན་འབད།',
