  'Delete selected users' => 'སེལ་འཐུ་འབད་ཡོད་པའི་ལག་ལེན་པ་ཚུ་བཏོན་གཏང་།',
  'Suspend selected users' => 'སེལ་འཐུ་འབད་ཡོད་མི་ལག་ལེན་པ་ཚུ་ འཕྲལ་བཀག་འབད།',
