  'This playlist belongs to your PlayHub account.' => 'འ་ནི་གླུ་གཞས་ཐོ་ཡིག་འདི་གིས་ ཁྱོད་ཀྱི་གླུ་གཞས་ཧབ་རྩིས་ཐོ་ལས་ གླུ་གཞས་ཐོ་ཡིག་ངོ་མ་དྲན་ཐོ་ཚུ་ལག་ལེན་འཐབ་ཨིན།',
  'Playlist stats' => 'གླུ་ཐོ་གནས་སྡུད།',
