  'Growth Hub' => 'འཕེལ་རྒྱས་ལྟེ་བ།',
  'Explore tools and tips to grow faster, improve your channel, and reach more viewers.' => 'མགྱོགས་དྲགས་སྦེ་ཡར་རྒྱས་གཏང་ནི་དང་ ཁྱོད་རའི་རྒྱུན་ལམ་ཡར་དྲག་གཏང་ནི་ དེ་ལས་ བལྟ་མི་མངམ་ལུ་ལྷོད་ནིའི་དོན་ལུ་ ལག་ཆས་དང་བསླབ་བྱ་ཚུ་འཚོལ་ཞིབ་འབད།',
  'Loading growth data...' => 'ཡར་འཕེལ་གྱི་གནད་སྡུད་མངོན་གསལ་འབད་དོ།',
  'Channel reach' => 'རྒྱུན་ལམ་ཁྱབ་ཚད།',
  'Engagement rate' => 'འབྲེལ་གཏོགས་ཚད་གཞི།',
  'Discovery videos' => 'གསར་རྙེད་བརྙན་འཕྲིན།',
  'Growth actions' => 'འཕེལ་བའི་བྱ་སྤྱོད།',
  'Based on your channel data' => 'ཁྱོད་རའི་རྒྱུ་ལམ་གནས་སྡུད་གཞི་བཞག་སྟེ།',
  'Publish consistently' => 'དུས་མཐུན་སྦེ་དཔར་བསྐྲུན་འབད།',
  'Upload your first video and give viewers a clear reason to subscribe.' => 'ཁྱོད་རའི་བརྙན་འཕྲིན་འགོ་དང་པ་འདི་ སྐྱེལ་བཙུགས་འབད་དེ་ བལྟ་མི་ཚུ་ལུ་ མཐུད་དགོ་པའི་རྒྱུ་མཚན་གསལ་ཏོག་ཏོ་ཅིག་བྱིན།',
  'Use Shorts for discovery' => 'འཚོལ་ཞིབ་ཀྱི་དོན་ལུ་ ཐུང་ཀུ་ཚུ་ལག་ལེན་འཐབ།',
  'Keep testing quick hooks and link viewers to longer videos.' => 'མགྱོགས་དྲགས་ཀྱི་ ཧུཀ་ཚུ་ བརྟག་དཔྱད་འབད་དེ་ བལྟ་མི་ཚུ་ བརྡ་དོན་རིངམོ་ཚུ་ལུ་ འབྲེལ་མཐུད་འབད།',
  'Create short vertical videos to reach viewers who have not found your channel yet.' => 'ཁྱོད་རའི་རྒྱུན་ལམ་འདི་ ད་ལྟོ་ཡང་མ་ཐོབ་མི་ བལྟ་མི་ཚུ་ལུ་ལྷོད་ནིའི་དོན་ལུ་ ཀེར་ཕྲང་བརྙན་འཕྲིན་ཐུང་ཀུ་ཚུ་བཟོ།',
  'Create short' => 'ཐུང་ཀུ་བཟོ།',
  'Turn comments into loyalty' => 'བསམ་འཆར་ཚུ་ ཐ་དམ་ཚིག་ལུ་བསྒྱུར།',
  'Reply to recent comments and turn viewers into returning fans.' => 'འཕྲལ་གྱི་བསམ་འཆར་ཚུ་ལུ་ལན་བཏབ་སྟེ་ བལྟ་མི་ཚུ་ ལོག་འོང་མི་ དགའ་མི་ལུ་བསྒྱུར་བཅོས་འབད།',
  'Ask a question in your next upload and reply quickly when comments arrive.' => 'ཁྱོད་རའི་ཤུལ་མམ་གྱི་སྐྱེལ་བཙུགས་ནང་དྲི་བ་ཅིག་དྲིས་ཞིནམ་ལས་ བསམ་འཆར་ཚུ་ལྷོདཔ་ད་ མགྱོགས་པ་རང་ལན་རྐྱབ།',
  'View comments' => 'བསམ་འཆར་བལྟ།',
  'Improve public reach' => 'མི་མང་ཁྱབ་སྤེལ་ཡར་དྲག་གཏང་ནི།',
  'Keep strong videos visible and refresh weak titles.' => 'བརྙན་འཕྲིན་སྒྲིང་སྒྲིང་ཚུ་མཐོང་ཚུགསཔ་སྦེ་བཞག་སྟེ་ མིང་ཚིག་ཞན་ཁོག་ཚུ་གསརཔ་བཟོ།',
  'Explore tools' => 'ལག་ཆས་ཚུ་འཚོལ་ཞིབ་འབད།',
  'Open the right workflow fast' => 'གཡས་ཀྱི་ལཱ་གི་རྒྱུན་རིམ་མགྱོགས་དྲགས་སྦེ་ཁ་ཕྱེ།',
  'Upload planner' => 'སྐྱེལ་བཙུགས་འཆར་གཞི་བཟོ་མི།',
  'Start a new upload with titles, tags, visibility, and thumbnail steps.' => 'ཁ་ཡིག་དང་ ངོ་རྟགས་ མཐོང་སྣང་ དེ་ལས་ མཐེབ་གཟེར་གྱི་རིམ་པ་ཚུ་དང་གཅིག་ཁར་ སྐྱེལ་བཙུགས་གསརཔ་ཅིག་འགོ་བཙུགས།',
  'Shorts studio' => 'གློག་བརྙན་ཐུང་ཐུང་བཟོ་ཁང་།',
  'Create short videos for faster discovery and mobile viewers.' => 'མགྱོགས་དྲགས་སྦེ་འཚོལ་ཞིབ་འབད་ནི་དང་ འགྲུལ་འཕྲིན་བལྟ་མི་ཚུ་གི་དོན་ལུ་ བརྡ་དོན་ཐུང་ཀུ་བཟོ།',
  'Content manager' => 'ནང་དོན་འཛིན་སྐྱོང་པ།',
  'Review visibility, monetization, comments, and performance in one place.' => 'མཐོང་སྣང་དང་ དངུལ་བཟོ་ནི་ བསམ་འཆར་ དེ་ལས་ ལཱ་འགན་ཚུ་ ས་གནས་གཅིག་ནང་ བསྐྱར་ཞིབ་འབད།',
  'Analytics review' => 'དབྱེ་དཔྱད་བསྐྱར་ཞིབ།',
  'Track views, likes, comments, publishing status, and trends.' => 'མཐོང་སྣང་དང་ དགའ་མི་ བསམ་བཀོད་ དཔར་བསྐྲུན་གནས་ཚད་ དེ་ལས་ འགྲོས་ཚུ་ བརྟག་ཞིབ་འབད།',
  'Channel profile' => 'རྒྱུ་ལམ་གསལ་སྡུད།',
  'Update your bio, channel details, and public creator presence.' => 'ཁྱོད་རའི་སྐྱེ་ལྡན་དང་ རྒྱུན་ལམ་ཁ་གསལ་ དེ་ལས་ མི་མང་གསར་བསྐྲུན་འབད་མི་གི་གནས་སྟངས་ཚུ་ དུས་མཐུན་བཟོ།',
  'Audience building' => 'ལྟདམོ་ལྟ་མི་བཟོ་སྐྲུན།',
  'Study subscribers, comments, and what viewers respond to most.' => 'མིང་ཐོ་བཀོད་མི་དང་ བསམ་འཆར་ དེ་ལས་ བལྟ་མི་ཚུ་གིས་ ལན་མང་ཤོས་རང་ ག་ཅི་བྱིནམ་ཨིན་ན་ ཞིབ་འཇུག་འབད།',
  'Top content to learn from' => 'ལྷབ་ནིའི་ནང་དོན་གཙོ་བོ།',
  'Upload videos to unlock performance lessons.' => 'ལས་རིམ་གྱི་སློབ་ཚན་ཚུ་ ལྡེ་མིག་ཕྱེ་ནིའི་དོན་ལུ་ བརྡ་དོན་ཚུ་སྐྱེལ་བཙུགས་འབད།',
  'Tips to reach more viewers' => 'བལྟ་མི་མངམ་ལུ་ལྷོད་ནིའི་བསླབ་བྱ།',
  'Creator checklist' => 'གསར་བསྐྲུན་པ་ཞིབ་དཔྱད་ཐོ་ཡིག།',
  'Hook viewers in the first 3 seconds' => 'སྐར་ཆ་ ༣ འགོ་ཐོག་ལུ་བལྟ་མི་ཚུ།',
  'Open with the result, conflict, or visual payoff before adding context.' => 'སྐབས་དོན་ཁ་སྐོང་མ་འབད་བའི་ཧེ་མ་ གྲུབ་འབྲས་དང་ འཁྲུག་རྩོད་ ཡང་ན་ མཐོང་སྣང་གི་ འཐུས་ཚུ་དང་གཅིག་ཁར་ ཁ་ཕྱེ།',
  'Make titles searchable' => 'ཁ་ཡིག་ཚུ་འཚོལ་ཞིབ་འབད་བཏུབ་བཟོ།',
  'Use the exact words viewers would type, then keep the promise in the video.' => 'བལྟ་མི་ཚུ་གིས་ཡིག་དཔར་རྐྱབ་མི་ཚིག་ངེས་བདེན་ཚུ་ལག་ལེན་འཐབ་སྟེ་ བརྙན་འཕྲིན་ནང་ལུ་ ཁས་བླངས་འདི་བཞག།',
  'Convert shorts into sessions' => 'ཐུང་ཐུང་ཚུ་ལཱ་ཡུན་ནང་ལུ་གཞི་བསྒྱུར་འབད།',
  'Pin a comment or description link from each short to a related full video.' => 'ཐུང་ཀུ་རེ་རེ་ལས་ འབྲེལ་ཡོད་བརྙན་འཕྲིན་ཆ་ཚང་ལུ་ བསམ་བརྗོད་ཡང་ན་ འགྲེལ་བཤད་འབྲེལ་ལམ་ཅིག་ པིན་འབད།',
  'Refresh underperforming uploads' => 'ལཱ་འབད་མ་ཚུགས་པའི་སྐྱེལ་བཙུགས་ཚུ་ གསར་བསྐྲུན་འབད།',
  'Update thumbnails and titles after you have enough impressions to compare.' => 'ཁྱོད་ལུ་ག་བསྡུར་འབད་ནི་ལུ་ མཐོང་སྣང་ལངམ་སྦེ་ཡོད་པའི་ཤུལ་ལས་ མཐེབ་གཟེར་དང་མགོ་མིང་ཚུ་དུས་མཐུན་བཟོ།',
  'Upload source' => 'སྐྱེལ་བཙུགས་འབྱུང་ཁུངས།',
  'Choose a local video file or import a public video from an enabled provider.' => 'ཉེ་གནས་ཀྱི་ཝི་ཌིའོ་ཡིག་སྣོད་གདམ་ཁ་རྐྱབས་ ཡང་ན་ ལྕོགས་ཅན་བྱིན་མི་ཅིག་ལས་ མི་མང་གི་ཝི་ཌིའོ་ནང་འདྲེན་འབད།',
  'Local upload' => 'ས་གནས་ཀྱི་སྐྱེལ་བསྐྱོད།',
  'Import from URL' => 'ཡུ་ཨར་ཨེལ་ལས་ནང་འདྲེན་འབད།',
  'Import video from URL' => 'ཡུ་ཨར་ཨེལ་ནང་ལས་ ཝི་ཌིའོ་ནང་འདྲེན་འབད།',
  'Select an enabled service and paste a public video URL. PlayHub will import it into the normal processing queue.' => 'ལྕོགས་ཅན་བཟོ་ཡོད་པའི་ཞབས་ཏོག་ཅིག་སེལ་འཐུ་འབད་ཞིནམ་ལས་ མི་མང་བརྙན་འཕྲིན་ཡུ་ཨར་ཨེལ་ཅིག་སྦྱར། PlayHub གིས་ སྤྱིར་བཏང་ལས་སྦྱོར་གྲལ་ཐིག་ནང་ལུ་ནང་འདྲེན་འབད་འོང་།',
  'Service' => 'ཞབས་ཏོག།',
  'Video URL' => 'བརྙན་འཕྲིན་གྱི་ཡུ་ཨར་ཨེལ།',
  'Direct video URL' => 'ཐད་ཀར་བརྙན་འཕྲིན་གྱི་ཡུ་ཨར་ཨེལ།',
  'YouTube' => 'YouTube',
  'Vimeo' => 'Vimeo',
  'Dailymotion' => 'Dailymotion',
  'Imports a public MP4, MOV, WEBM, MKV, AVI, or M4V file URL.' => 'མི་མང་ཨེམ་པི་༤, ཨེམ་ཨོ་ཝི་, ཝེ་བི་ཨེམ་, ཨེམ་ཀེ་ཝི་, ཨེ་ཝི་ཨའི་, ཡང་ན་ ཨེམ་༤ཝི་ཡིག་སྣོད་ཡུ་ཨར་ཨེལ་ཅིག་ནང་འདྲེན་འབདཝ་ཨིན།',
  'Requires a downloader command such as yt-dlp for media import.' => 'བརྡ་ལམ་ནང་འདྲེན་གྱི་དོན་ལུ་ yt-dlp བཟུམ་གྱི་ཕབ་ལེན་འབད་མི་བརྡ་བཀོད་ཅིག་དགོཔ་ཨིན།',
  'Import queue' => 'གྲལ་ཐིག་ནང་འདྲེན་འབད།',
  'Generated after import' => 'ནང་འདྲེན་འབད་བའི་ཤུལ་ལས་བཟོ་བཏོན་འབད་ཡོདཔ།',
  'A thumbnail is created during processing.' => 'ལས་སྦྱོར་འབད་བའི་སྐབས་ མཐེབ་གཟེར་ཅིག་གསར་བསྐྲུན་འབདཝ་ཨིན།',
  'Complete the import details first.' => 'དང་པ་རང་ ནང་འདྲེན་རྒྱས་བཤད་ཚུ་མཇུག་བསྡུ།',
  'Import source' => 'ནང་འདྲེན་འབྱུང་ཁུངས།',
  'Import summary' => 'ནང་འདྲེན་སྙིང་བསྡུས།',
  'Source URL' => 'འབྱུང་ཁུངས་ཡུ་ཨར་ཨེལ།',
  'Video imported' => 'བརྙན་འཕྲིན་ནང་འདྲེན་འབད་ཡོདཔ།',
  'Your video was imported and processing has started.' => 'ཁྱོད་ཀྱི་ཝི་ཌིའོ་འདི་ནང་འདྲེན་འབད་དེ་ ལས་སྦྱོར་འགོ་བཙུགས་ཡོདཔ།',
  'Import Video' => 'བརྙན་འཕྲིན་ནང་འདྲེན།',
  'Import a public video URL, customize its details, and publish it through the normal processing pipeline.' => 'མི་མང་བརྙན་འཕྲིན་ཡུ་ཨར་ཨེལ་ནང་འདྲེན་འབད་ཞིནམ་ལས་ དེ་གི་ཁ་གསལ་ཚུ་སྲོལ་སྒྲིག་འབད་ཞིནམ་ལས་ སྤྱིར་བཏང་ལས་སྦྱོར་གྱི་མདོང་ལམ་བརྒྱུད་དེ་དཔར་བསྐྲུན་འབད།',
  'Video Import' => 'བརྙན་འཕྲིན་ནང་འདྲེན།',
  'Enable importing videos from supported external providers.' => 'རྒྱབ་སྐྱོར་འབད་ཡོད་པའི་ཕྱིའི་བྱིན་མི་ཚུ་ལས་ ཝི་ཌིའོ་ཚུ་ནང་འདྲེན་འབད་ནི་ལྕོགས་ཅན་བཟོ།',
  'Downloader Command' => 'ཕབ་ལེན་འབད་མི་བརྡ་བཀོད།',
  'YouTube Data API key' => 'ཡུ་ཊུབ་གནས་སྡུད་ཨེ་པི་ཨའི་ལྡེ་མིག།',
  'Vimeo access token' => 'ཝི་མིའོ་འཛུལ་སྤྱོད་བརྡ་རྟགས།',
  'Dailymotion API key' => 'ཌེ་ལི་མོ་ཤཱན་ཨེ་པི་ཨའི་ལྡེ་མིག།',
  'API Key' => 'ཨེ་པི་ཨའི་ལྡེ་མིག',
  'Not required' => 'དགོས་མཁོ་མེད།',
  'Save Import Settings' => 'ནང་འདྲེན་སྒྲིག་སྟངས་ཚུ་སྲུངས།',
  'Video import settings saved.' => 'ཝི་ཌིའོ་ནང་འདྲེན་སྒྲིག་སྟངས་སྲུང་བཞག་འབད་ཡོདཔ།',
  'Video import started.' => 'ཝི་ཌིའོ་ནང་འདྲེན་འགོ་བཙུགས་ཡོདཔ།',
  'This video import provider is disabled.' => 'བརྙན་འཕྲིན་ནང་འདྲེན་བྱིན་མི་འདི་ལྕོགས་མིན་བཟོ་ཡོདཔ་ཨིན།',
  'Video import provider is disabled.' => 'ཝི་ཌིའོ་ནང་འདྲེན་བྱིན་མི་འདི་ལྕོགས་མིན་བཟོ་ཡོདཔ།',
  'Direct imports must use a supported video file URL.' => 'ཐད་ཀར་དུ་ནང་འདྲེན་འབད་མི་ཚུ་གིས་ རྒྱབ་སྐྱོར་འབད་ཡོད་པའི་ཝི་ཌིའོ་ཡིག་སྣོད་ཡུ་ཨར་ཨེལ་ ལག་ལེན་འཐབ་དགོ།',
  'Cannot open remote video URL.' => 'ཐག་རིང་ཝི་ཌིའོ་ཡུ་ཨར་ཨེལ་ཁ་ཕྱེ་མི་ཚུགས།',
  'Cannot prepare imported video file.' => 'ནང་འདྲེན་འབད་ཡོད་པའི་ཝི་ཌིའོ་ཡིག་སྣོད་གྲ་སྒྲིག་འབད་མི་ཚུགས།',
  'Cannot read remote video file.' => 'ཐག་རིང་གི་ཝི་ཌིའོ་ཡིག་སྣོད་ལྷག་མི་ཚུགས།',
  'Imported video exceeds the maximum upload size.' => 'ནང་འདྲེན་འབད་ཡོད་པའི་ཝི་ཌིའོ་དེ་ སྐྱེལ་བཙུགས་ཚད་མཐོ་ཤོས་ལས་བརྒལ་ཏེ་ཡོད།',
  'Remote video file is empty.' => 'ཐག་རིང་གི་ཝི་ཌིའོ་ཡིག་སྣོད་འདི་སྟོངམ་ཨིན།',
  'Video import downloader command is not configured.' => 'ཝི་ཌིའོ་ནང་འདྲེན་ཕབ་ལེན་འབད་མི་བརྡ་བཀོད་འདི་རིམ་སྒྲིག་མ་འབད་བས།',
  'Downloader did not create an importable video file.' => 'ཕབ་ལེན་པ་གིས་ ནང་འདྲེན་འབད་བཏུབ་པའི་ ཝི་ཌིའོ་ཡིག་སྣོད་ཅིག་ གསར་བསྐྲུན་མ་འབད་བས།',
  'Import URL is invalid.' => 'ནང་འདྲེན་ཡུ་ཨར་ཨེལ་འདི་ནུས་མེད་ཨིན།',
  'Import URL must use HTTP or HTTPS.' => 'ནང་འདྲེན་ཡུ་ཨར་ཨེལ་འདི་ ཨེཆ་ཊི་ཊི་པི་ ཡང་ན་ ཨེཆ་ཊི་ཊི་པི་ཨེསི་ལག་ལེན་འཐབ་དགོ།',
  'Import URL host is invalid.' => 'ནང་འདྲེན་ཡུ་ཨར་ཨེལ་ཧོསིཊི་འདི་ནུས་མེད་ཨིན།',
  'Import URL does not match the selected provider.' => 'ནང་འདྲེན་ཡུ་ཨར་ཨེལ་འདི་ སེལ་འཐུ་འབད་ཡོད་པའི་བྱིན་མི་ལུ་མཐུན་སྒྲིག་མི་འབད།',
  'Import URL host cannot be resolved.' => 'ནང་འདྲེན་ཡུ་ཨར་ཨེལ་ཧོསཊི་འདི་སེལ་འཐུ་འབད་མི་ཚུགས།',
  'Import URL must resolve to a public host.' => 'ནང་འདྲེན་ཡུ་ཨར་ཨེལ་འདི་ མི་མང་ཧོསིཊི་ཅིག་ལུ་ བསལ་དགོཔ་ཨིན།',
  'Unknown video import provider.' => 'མ་ཤེས་པའི་བརྙན་འཕྲིན་ནང་འདྲེན་བྱིན་མི།',
  'Saves a public video file URL and plays it from the original URL.' => 'མི་མང་གི་ཝི་ཌིའོ་ཡིག་སྣོད་ཡུ་ཨར་ཨེལ་ཅིག་སྲུངམ་ཨིནམ་དང་ ཡུ་ཨར་ཨེལ་ངོ་མ་ལས་གཏངམ་ཨིན།',
  'Fetches YouTube details and plays with the YouTube embed player.' => 'ཡུ་ཊུབ་ཁ་གསལ་ཚུ་ལེན་ཞིནམ་ལས་ ཡུ་ཊུབ་བཙུགས་འཕྲུལ་དང་གཅིག་ཁར་རྩེདཝ་ཨིན།',
  'Fetches Vimeo details and plays with the Vimeo embed player.' => 'ཝི་མིའོ་ཁ་གསལ་ཚུ་ལེན་ཞིནམ་ལས་ ཝི་མིའོ་བཙུགས་གཏང་འབད་མི་དང་གཅིག་ཁར་རྩེདཝ་ཨིན།',
  'Fetches Dailymotion details and plays with the Dailymotion embed player.' => 'ཌེ་ལི་མོ་ཤཱན་ཁ་གསལ་ཚུ་འབག་འོང་ཞིནམ་ལས་ ཌེ་ལི་མོ་ཤཱན་བཙུགས་གཏང་མི་དང་གཅིག་ཁར་རྩེདཝ་ཨིན།',
  'Select an enabled service and paste a public video URL. PlayHub will fetch the details and play it from the original provider.' => 'ལྕོགས་ཅན་བཟོ་ཡོད་པའི་ཞབས་ཏོག་ཅིག་སེལ་འཐུ་འབད་ཞིནམ་ལས་ མི་མང་བརྙན་འཕྲིན་ཡུ་ཨར་ཨེལ་ཅིག་སྦྱར། PlayHub གིས་ཁ་གསལ་ཚུ་འབག་འོང་སྟེ་ བྱིན་མི་ངོ་མ་ལས་ རྩེད་འོང་།',
  'Fetching...' => 'འབག་འོང་དོ།',
