  'Save alerts' => 'དྲན་བསྐུལ་ཚུ་སྲུངས།',
  'Save Live Streaming Settings' => 'ཐད་གཏོང་སྒྲིག་སྟངས་ཚུ་སྲུངས།',
  'Save pinned message' => 'པིན་འབད་ཡོད་པའི་འཕྲིན་དོན་སྲུངས།',
  'Save replay' => 'བསྐྱར་གཏང་སྲུང་བཞག་འབད།',
  'Save stream labels' => 'རྒྱུན་ལམ་ཁ་ཡིག་ཚུ་སྲུངས།',
  'Save Website Configuration' => 'ཡོངས་འབྲེལ་རིམ་སྒྲིག་སྲུངས།',
  'Saved polls' => 'འོས་བསྡུ་སྲུང་བཞག་འབད་ཡོདཔ།',
  'Saved with this live stream draft.' => 'ཐད་གཏོང་ཟིན་བྲིས་འདི་དང་གཅིག་ཁར་སྲུང་བཞག་འབད་ཡོདཔ།',
  'Scheduling and tool limits' => 'དུས་ཚོད་བཀོད་སྒྲིག་དང་ལག་ཆས་ཚད་གཞི།',
  'Section title size' => 'ཚན་པའི་ཁ་བྱང་ཚད།',
  'Send response' => 'ལན་བསྐུར།',
  'Separate terms with commas' => 'ཐ་སྙད་སོ་སོར་ལྷོད་རྟགས་བཀོད།',
  'Separate usernames with commas' => 'ལག་ལེན་པའི་མིང་ཚུ་ལྷོད་རྟགས་དང་གཅིག་ཁར་སོ་སོ་འཕྱལ།',
  'Shape & Layout' => 'དབྱིབས་དང་བཀོད་སྒྲིག།',
  'Sidebar width' => 'ཟུར་ཁའི་ཕྲ་རིང་གི་རྒྱ་ཚད།',
  'Signed-in viewers' => 'ནང་བསྐྱོད་འབད་ཡོད་མི་ལྟདམོ་ལྟ་མི་ཚུ།',
  'Slow mode interval' => 'དལ་བའི་ཐབས་ལམ་བར་མཚམས།',
