  'Standard moderation' => 'ཚད་ལྡན་ཚད་འཛིན།',
  'Start camera preview' => 'པར་ཆས་སྔོན་ལྟ་འགོ་བཙུགས།',
  'Start unavailable' => 'འཐོབ་མི་ཚུགས་འགོ་བཙུགས།',
  'Starts in' => '2016 ལོར་འགོ་བཙུགས།',
  'Stream labels' => 'རྒྱུན་ལམ་ཁ་ཡིག་ཚུ།',
  'Streaming engine not configured' => 'རྒྱུག་འཕྲུལ་རིམ་སྒྲིག་མ་འབད་བས།',
  'Streaming engine required' => 'རྒྱུན་ལམ་འཕྲུལ་འཁོར་དགོཔ།',
  'Strict moderation' => 'ཚད་འཛིན་དམ་པོ།',
  'Strong border' => 'ས་མཚམས་བརྟན་པོ།',
  'Subscription alerts' => 'མཁོ་མངགས་དྲན་སྐུལ་ཚུ།',
