  'Support ticket' => 'རྒྱབ་སྐྱོར་འཛིན་བྱང་།',
  'Target bitrate (Kbps)' => 'དམིགས་གཏད་བིཊི་རེཊི་ (ཀེ་བི་པི་ཨེསི་)',
  'Tell viewers what this live stream is about' => 'ལྟདམོ་ལྟ་མི་ཚུ་ལུ་ ཐད་གཏོང་འདི་ག་ཅི་གི་སྐོར་ལས་ཨིན་ན་སླབ།',
  'The logo must be an SVG file.' => 'ལས་རྟགས་འདི་ ཨེསི་ཝི་ཇི་ཡིག་སྣོད་ཅིག་འོང་དགོ།',
  'Topbar height' => 'མགོའི་ཕྲ་རིང་མཐོ་ཚད།',
  'Ultra-low latency' => 'ཧ་ཅང་དམའ་བའི་འགོར་ཚད།',
  'Upload speed' => 'སྐྱེལ་བཙུགས་ཀྱི་མགྱོགས་ཚད།',
  'User message' => 'ལག་ལེན་པའི་འཕྲིན་དོན།',
  'user@example.com, creator@example.com' => 'user@དཔེ་རིས་.com, གསར་བསྐྲུན་པ་@དཔེ་རིས་.com',
  'Webcam preview' => 'ཝེབ་པར་ཆས་སྔོན་ལྟ།',
  'Webcam preview works locally. Public broadcasting and RTMP credentials will be added with the streaming engine.' => 'ཝེབ་པར་ཆས་སྔོན་ལྟ་འདི་ཉེ་གནས་ལུ་ལཱ་འབདཝ་ཨིན། མི་མང་རྒྱང་བསྒྲགས་དང་ RTMP གི་ཡིག་ཆ་ཚུ་ རྒྱུན་སྤེལ་འཕྲུལ་ཆས་དང་གཅིག་ཁར་ ཁ་སྐོང་བརྐྱབ་འོང་།',
  'Website Colors' => 'དྲ་ཚིགས་ཀྱི་ཚོས་གཞི།',
  'Website Configuration' => 'དྲ་ཚིགས་རིམ་སྒྲིག།',
  'Website configuration not saved' => 'ཡོངས་འབྲེལ་རིམ་སྒྲིག་སྲུང་བཞག་མ་འབད་བས།',
  'Write the reply that will be saved and emailed to the user...' => 'ལག་ལེན་པ་ལུ་སྲུང་བཞག་འབད་དེ་གློག་འཕྲིན་གཏང་ནི་ཨིན་པའི་ལན་འདི་བྲིས།',
  'Your studio settings can be prepared now. Public broadcasting will be enabled with the media engine.' => 'ཁྱོད་ཀྱི་སྒྲ་བཟུང་སྒྲིག་སྟངས་ཚུ་ད་ལྟོ་གྲ་སྒྲིག་འབད་ཚུགས། མི་མང་རྒྱང་བསྒྲགས་འདི་ བརྡ་བརྒྱུད་འཕྲུལ་ཆས་དང་གཅིག་ཁར་ ལྕོགས་ཅན་བཟོ་ནི་ཨིན།',
  'Activate poll' => 'འོས་བསྡུ་ཤུགས་ལྡན་བཟོ།',
  'Cancel edit' => 'ཞུན་དག་བཤོལ།',
  'Close poll' => 'འོས་བསྡུ་ཁ་བསྡམས།',
  'Creator defaults' => 'གསར་བསྐྲུན་པ་སྔོན་སྒྲིག་ཚུ།',
  'Edit poll' => 'འོས་བསྡུ་ཞུན་དག་འབད།',
  'Save poll' => 'འོས་བསྡུ་སྲུང་བཞག་འབད།',
  'Schedule poll' => 'ལས་འཆར་འོས་བསྡུ།',
  'Webcam preview is disabled by the site administrator.' => 'ཝེབ་ཀེམ་སྔོན་ལྟ་འདི་ས་ཁོངས་བདག་སྐྱོང་པ་གིས་ལྕོགས་མིན་བཟོ་ཡོདཔ་ཨིན།',
  'WebRTC engine configured on this server' => 'སར་བར་འདི་གུ་ WebRTC འཕྲུལ་འཁོར་རིམ་སྒྲིག་འབད་ཡོདཔ།',
  'Set the LiveKit server credentials to enable broadcasting' => 'རྒྱང་བསྒྲགས་ལྕོགས་ཅན་བཟོ་ནིའི་དོན་ལུ་ ལའིབ་ཀིཊི་སར་བར་གྱི་ཆོག་ཡིག་ཚུ་གཞི་སྒྲིག་འབད།',
  'LiveKit WebRTC is ready for browser broadcasting.' => 'LiveKit WebRTC འདི་ བརྡ་འཚོལ་རྒྱང་བསྒྲགས་འབད་ནིའི་དོན་ལུ་ གྲ་སྒྲིག་ཡོདཔ་ཨིན།',
  'Webcam preview works locally. Public broadcasting requires the LiveKit media engine.' => 'ཝེབ་པར་ཆས་སྔོན་ལྟ་འདི་ས་གནས་ནང་ལཱ་འབདཝ་ཨིན། མི་མང་རྒྱང་བསྒྲགས་ལུ་ LiveKit བརྡ་བརྒྱུད་འཕྲུལ་ཆས་དགོཔ་ཨིན།',
  'You are live' => 'ཁྱོད་འཚོ་བཞིན་ཡོད།',
  'Your camera and microphone are publishing through LiveKit.' => 'ཁྱོད་ཀྱི་པར་ཆས་དང་སྐད་འཕྲིན་འདི་ LiveKit བརྒྱུད་དེ་དཔར་བསྐྲུན་འབད་བཞིན་ཡོད།',
  'Ending...' => 'མཇུག་སྒྲིལ།',
  'End live stream' => 'ཐད་གཏོང་མཇུག་སྒྲིལ།',
  'Connecting to live stream...' => 'ཐད་གཏོང་ལ་མཐུད་བཞིན་ཡོད།...',
  'This stream has not started yet.' => 'ཆུ་རྒྱུན་འདི་ད་དུང་འགོ་མ་བཙུགས་པས།',
  'No chat messages yet.' => 'ད་དུང་ཁ་བརྡ་བརྡ་འཕྲིན་མེད།',
  'Sign in to join live chat' => 'ཐད་གཏོང་ཁ་བརྡའི་ནང་འཛུལ་ཞུགས་འབད།',
  'Creator goal' => 'བཟོ་མཁན་གྱི་དམིགས་ཡུལ།',
  'Unable to connect to this live stream.' => 'ཐད་གཏོང་འདི་ལ་མཐུད་མི་ཐུབ།',
  'Unable to send the chat message.' => 'ཁ་བརྡའི་འཕྲིན་དོན་གཏོང་མི་ཐུབ།',
  'Unable to start the live stream.' => 'ཐད་གཏོང་འགོ་འཛུགས་མི་ཐུབ།',
  'Unable to end the live stream.' => 'ཐད་གཏོང་མཇུག་བསྡུ་མི་ཐུབ།',
  'LiveKit connection details are unavailable.' => 'LiveKit མཐུད་ལམ་ཁ་གསལ་ཚུ་ཐོབ་མི་ཚུགས།',
  'A working camera and microphone are required to start broadcasting.' => 'རྒྱང་བསྒྲགས་འགོ་བཙུགས་ནིའི་དོན་ལུ་ ལཱ་འབད་བའི་པར་ཆས་དང་སྐད་འཕྲིན་དགོཔ་ཨིན།',
  'Start the camera preview and allow camera and microphone access before broadcasting.' => 'པར་ཆས་སྔོན་ལྟ་འགོ་བཙུགས་ཏེ་ རྒྱང་བསྒྲགས་མ་འབད་བའི་ཧེ་མ་ པར་ཆས་དང་སྐད་འཕྲིན་འཛུལ་སྤྱོད་འབད་བཅུག།',
  'LiveKit WebRTC currently requires the webcam source.' => 'ད་ལྟོ་ LiveKit WebRTC ལུ་ ཝེབ་པར་ཆས་ཀྱི་འབྱུང་ཁུངས་དགོཔ་ཨིན།',
  'Start the live stream before activating its media source.' => 'དེ་གི་བརྡ་བརྒྱུད་འབྱུང་ཁུངས་ཤུགས་ལྡན་མ་བཟོ་བའི་ཧེ་མ་ ཐད་གཏོང་འགོ་བཙུགས།',
  'LiveKit is not configured.' => 'ལའིབ་ཀིཊི་རིམ་སྒྲིག་མ་འབད་བས།',
  'Sign in to watch this live stream.' => 'ཐད་གཏོང་འདི་བལྟ་བར་ནང་བསྐྱོད་བྱོས།',
  'LiveKit server configuration' => 'ལའིབ་ཀིཊི་སར་བར་རིམ་སྒྲིག།',
  'Docker image' => 'ཌོག་ཀར་གཟུགས་བརྙན།',
  'Container status' => 'དོས་ཆས་ཀྱི་གནས་ཚད།',
  'Running' => 'གཡོག་བཀོལ་དོ།',
  'Stopped' => 'བཀག་ཡོདཔ།',
  'WebRTC engine is accepting connections' => 'ཝེབ་ཨར་ཊི་སི་འཕྲུལ་ཆས་ཀྱིས་ མཐུད་ལམ་ཚུ་དང་ལེན་འབད་དོ།',
  'Save configuration to request a container restart' => 'ཀོན་ཊེ་ནར་ལོག་འགོ་བཙུགས་ཀྱི་ཞུ་བ་འབད་ནི་ལུ་ རིམ་སྒྲིག་སྲུངས།',
  'Enable LiveKit server' => 'ལའིབ་ཀིཊི་སར་བར་ལྕོགས་ཅན་བཟོ།',
  'LiveKit WebSocket URL' => 'ལའིབ་ཀིཊི་ཝེབ་སོ་ཀེཊི་ཡུ་ཨར་ཨེལ།',
