  'The invited user must sign in with that account before opening the link.' => 'འབོ་ཡོད་པའི་ལག་ལེན་པ་འདི་གིས་ འབྲེལ་ལམ་ཁ་མ་ཕྱེ་བའི་ཧེ་མ་ རྩིས་ཐོ་དེ་དང་གཅིག་ཁར་ ནང་བསྐྱོད་འབད་དགོ།',
  'The logo must be a safe SVG file.' => 'ལས་རྟགས་འདི་ ཉེན་སྲུང་ཡོད་པའི་ SVG ཡིག་སྣོད་ཅིག་འོང་དགོ།',
  'The new password must be different from the current one.' => 'ཆོག་ཡིག་གསརཔ་འདི་ ད་ལྟོའི་ཆོག་ཡིག་དང་སོ་སོ་འོང་དགོ།',
  'The provided credentials are incorrect.' => 'བྱིན་ཡོད་པའི་ངོ་རྟགས་ཚུ་ འཛོལ་བ་ཨིན།',
  'The two-factor authentication code is invalid.' => 'ཆ་རྐྱེན་གཉིས་ཀྱི་བདེན་བཤད་ཨང་རྟགས་འདི་ནུས་མེད་ཨིན།',
  'This account has been suspended. Contact support if you believe this is a mistake.' => 'རྩིས་ཐོ་འདི་བཀག་བཞག་ཡོད། འདི་འཛོལ་བ་ཨིནམ་སྦེ་ཡིད་ཆེས་བསྐྱེད་པ་ཅིན་ རྒྱབ་སྐྱོར་ལུ་འབྲེལ་བ་འཐབ།',
  'this control session' => 'ཚད་འཛིན་ལཱ་ཡུན་འདི།',
  'This is a replay of the live chat.' => 'འདི་ཐད་གཏོང་ཁ་སླབ་ཀྱི་བསྐྱར་གཏང་ཅིག་ཨིན།',
  'This live stream is private.' => 'ཐད་གཏོང་འདི་སྒེར་གྱི་ཨིན།',
  'Thumbnail already available.' => 'མཐེབ་གཟེར་ཧེ་མ་ལས་ཐོབ་ཚུགས།',
  'Thumbnail uploaded.' => 'མཐེབ་གཟེར་སྐྱེལ་བཙུགས་འབད་ཡོདཔ།',
  'Ticket details are unavailable.' => 'ཤོག་འཛིན་གྱི་ཁ་གསལ་ཚུ་ འཐོབ་མི་ཚུགས།',
  'Tips & Gifts' => 'བསླབ་བྱ་དང་ལག་རྟགས།',
  'Top Moments' => 'དུས་སྐབས་མཐོ་ཤོས་',
