  'Unable to send a verification code to the selected method.' => 'སེལ་འཐུ་འབད་ཡོད་པའི་ཐབས་ལམ་ལུ་ བདེན་བཤད་ཨང་རྟགས་གཏང་མི་ཚུགས།',
  'Use an HTTPS, HTTP, or website-relative URL.' => 'ཨེཆ་ཊི་ཊི་པི་ཨེསི་ ཨེཆ་ཊི་ཊི་པི་ ཡང་ན་ ཡོངས་འབྲེལ་འཆར་སྒོ་དང་འབྲེལ་བའི་ ཡུ་ཨར་ཨེལ་ཅིག་ལག་ལེན་འཐབ།',
  'Used for invoices, receipts, and billing support.' => 'བྱུང་འཛིན་དང་ འོང་འབབ་ དེ་ལས་ བྱུང་འཛིན་རྒྱབ་སྐྱོར་གྱི་དོན་ལུ་ ལག་ལེན་འཐབ་ཡོདཔ་ཨིན།',
  'Use logout to sign out from the current device.' => 'ད་ལྟོའི་ཐབས་འཕྲུལ་ལས་ཕྱིར་བསྐྱོད་འབད་ནི་ལུ་ ཕྱིར་བསྐྱོད་ལག་ལེན་འཐབ།',
  'Verified account' => 'བདེན་དཔྱད་འབད་ཡོད་པའི་རྩིས་ཐོ།',
